workloads.sieve-array:
fn benchmark() -> i64 {
    let one = (1 + benchmark_seed()) as i32;
    let mut flags = [one; 256];
    let mut p = 2usize;
    while p * p < 256 {
        if flags[p] != 0 {
            let mut k = p * p;
            while k < 256 {
                flags[k] = 0;
                k += p;
            }
        }
        p += 1;
    }
    flags[2..].iter().map(|&value| i64::from(value)).sum()
}

workloads.towers-recursive:
#[inline(never)]
fn towers(n: i64) -> i64 {
    if n == 0 { 0 } else { 1 + towers(n - 1) + towers(n - 1) }
}
fn benchmark() -> i64 {
    towers(18 + benchmark_seed())
}

workloads.queens-backtracking:
fn queens_safe(cols: &[i32; 8], row: usize, col: i32) -> bool {
    for prior in 0..row {
        let placed = cols[prior];
        if placed == col || (placed - col).abs() == (row - prior) as i32 {
            return false;
        }
    }
    true
}
fn queens_place(cols: &mut [i32; 8], row: usize, size: usize) -> i64 {
    if row == size {
        return 1;
    }
    let mut total = 0i64;
    for col in 0..size {
        if queens_safe(cols, row, col as i32) {
            cols[row] = col as i32;
            total += queens_place(cols, row + 1, size);
        }
    }
    total
}
fn benchmark() -> i64 {
    let size = (8 + benchmark_seed()) as usize;
    let mut cols = [0i32; 8];
    queens_place(&mut cols, 0, size)
}

workloads.heap-permute:
fn heap_permute(values: &mut [i32; 8], n: usize) -> i64 {
    if n == 1 {
        return 1;
    }
    let mut total = 0i64;
    for i in 0..n {
        total += heap_permute(values, n - 1);
        let j = if n % 2 == 0 { i } else { 0 };
        values.swap(j, n - 1);
    }
    total
}
fn benchmark() -> i64 {
    let n = (8 + benchmark_seed()) as usize;
    let mut values = [0, 1, 2, 3, 4, 5, 6, 7];
    heap_permute(&mut values, n)
}

workloads.ackermann-deep:
#[inline(never)]
fn ackermann(m: i64, n: i64) -> i64 {
    if m == 0 {
        n + 1
    } else if n == 0 {
        ackermann(m - 1, 1)
    } else {
        ackermann(m - 1, ackermann(m, n - 1))
    }
}
fn benchmark() -> i64 {
    ackermann(3, 8 + benchmark_seed())
}

workloads.tak-branching:
#[inline(never)]
fn tak(x: i64, y: i64, z: i64) -> i64 {
    if x <= y {
        z
    } else {
        tak(tak(x - 1, y, z), tak(y - 1, z, x), tak(z - 1, x, y))
    }
}
fn benchmark() -> i64 {
    tak(18 + benchmark_seed(), 12, 6)
}

workloads.collatz-range:
fn benchmark() -> i64 {
    let limit = 10_000 + benchmark_seed();
    let mut total = 0i64;
    for n in 1..=limit {
        let mut value = n;
        while value != 1 {
            value = if value % 2 == 0 { value / 2 } else { 3 * value + 1 };
            total += 1;
        }
    }
    total
}

workloads.matrix-multiply:
fn benchmark() -> i64 {
    let seed = benchmark_seed();
    let mut a = [0i64; 16];
    let b = [1i64, 4, 7, 10, 13, 16, 2, 5, 8, 11, 14, 0, 3, 6, 9, 12];
    let mut c = [0i64; 16];
    for (index, value) in a.iter_mut().enumerate() {
        *value = index as i64 + 1 + seed;
    }
    let iterations = (100 + seed) as usize;
    for iteration in 0..iterations {
        let _ = black_box(iteration);
        let a = black_box(&a);
        let b = black_box(&b);
        for row in 0..4 {
            for col in 0..4 {
                let mut value = 0i64;
                for k in 0..4 {
                    value += a[row * 4 + k] * b[k * 4 + col];
                }
                c[row * 4 + col] = value;
            }
        }
        black_box(&mut c);
    }
    c.iter().sum()
}
